                'table' => "theme_download",
                'findSql' => "select * from information_schema.tables where table_name ='@table'",
                'sql' => "CREATE TABLE IF NOT EXISTS `@table` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '模版名称',
  `tid` int(11) NOT NULL DEFAULT '0' COMMENT '模版ID',
  `download_time` int(11) NOT NULL DEFAULT '0' COMMENT '下载时间',
  `download_url` varchar(500) NOT NULL DEFAULT '' COMMENT '下载地址',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='主题下载记录表';"
